for n in range(101, 110):
    U[f'TC-{n}'] = (None, 'The report generates without errors (results table or "no records"); when the QA market has kiosk sales, its values match.')

def apply(path, key_col):
    w = openpyxl.load_workbook(path); t = w['Test Cases']; done = []
    for r in range(2, t.max_row + 1):
        k = t.cell(r, key_col).value
        if k in U:
            steps, exp = U[k]
            if steps: t.cell(r, 6).value = steps
            t.cell(r, 7).value = exp
            done.append(k)
    w.save(path); return done
print('data/', len(apply('data/End_to_End_QA_Test_Cases.xlsx', 1)))
print('reports/', len(apply('reports/Execution_Results.xlsx', 1)))
print('Updated (by Old TC ID)', len(apply('End_to_End_QA_Test_Cases_Updated.xlsx', 11)))
